  const Calisanlar = emps.map(e => ({ CalisanNo: e[0], AdSoyad: e[1] + ' ' + e[2], DepartmanNo: e[3] || 0, YoneticiNo: e[4], Unvan: e[5], Maas: e[6], IseGiris: D(e[7]), Eposta: e[8], Yol: pathOf(e[0]), Seviye: pathOf(e[0]).split('|').length, KidemYil: Math.floor((Date.UTC(2024, 11, 31) - D(e[7]).getTime()) / (365.25 * 86400000)) }));
  if (!Departmanlar.some(d => d.DepartmanNo === 0)) Departmanlar.push({ DepartmanNo: 0, Departman: 'Genel Müdürlük', Sehir: 'İstanbul' });
  const reps = emps.filter(e => e[3] === 1).map(e => e[0]);

