  const bandOf = x => x === 0 ? 'İndirimsiz' : x <= 0.1 ? '%5–10' : '%15–20';
  const Satislar = items.map(it => {
    const o = ordById[it[1]], p = prodById[it[2]]; const d = D(o[2]); const sd = shipDays[o[0]];
    const tutar = Math.round(it[3] * it[4] * (1 - it[5]) * 100) / 100;
