  bulb: '<path d="M9 18h6M10 21h4"/><path d="M12 3a6 6 0 00-3.5 10.9c.6.5 1 1.2 1 2.1h5c0-.9.4-1.6 1-2.1A6 6 0 0012 3z"/>'
};
const ic = (n, sw) => '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="' + (sw || 2) + '" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + (ICON[n] || '') + '</svg>';
const NAV = [
  ['Öğren', [['home', 'Ana sayfa', 'home'], ['paths', 'Patikalar', 'path'], ['curr', 'Dersler (A1–C2)', 'book'], ['test', 'Seviye testi', 'target']]],
  ['Uygula', [['studio', 'DAX Stüdyosu', 'term'], ['lab', 'Ölçü Laboratuvarı', 'flask'], ['dash', 'Dashboardlar', 'dash'], ['final', 'Final Projesi', 'flag']]],
  ['Başvuru', [['menus', 'Power BI Menüleri', 'menu'], ['visuals', 'Görseller ve Biçim', 'chart'], ['tricks', 'Püf Noktaları', 'bulb'], ['formulas', 'DAX Formülleri', 'fx'], ['model', 'Veri Modeli', 'model'], ['dict', 'Sözlük', 'dict']]]
];
