function spanW(span) { const ww = window.innerWidth; const eff = ww <= 760 ? 12 : ww <= 1080 ? (span <= 3 ? 6 : 12) : span; const inner = mainW() - 34; return Math.max(260, Math.round((inner - (12 / eff - 1) * 12) * eff / 12) - 34); }
