  return '<section class="lvl-block"><div class="sec-head"><div><span class="eyebrow">Hazır ölçüler</span><h2>Bu modelin ölçü kütüphanesi (' + LIB.length + ')</h2></div><button class="btn sm" data-go="lab">Uzun kalıplar: Ölçü Laboratuvarı</button></div><p class="muted" style="margin:0;max-width:70ch">Dashboardlar ve alıştırmalar bu ölçüleri kullanır. İyi bir model ölçüleri birbirinin üzerine kurar: temel ölçüler bir kez tanımlanır, diğerleri onları çağırır.</p><div class="panel"><div class="coltable"><table><thead><tr><th>Ölçü</th><th>Seviye</th><th>Formül</th><th>Açıklama</th></tr></thead><tbody>' + LIB.map(m => '<tr><td>[' + esc(m.name) + ']</td><td>' + (lv(m) ? lvBadge(lv(m)) : '') + '</td><td><code class="mcode">' + hl(m.expr.length > 420 ? m.expr.slice(0, 420) + '\n…' : m.expr) + '</code></td><td>' + esc(m.desc || '') + '</td></tr>').join('') + '</tbody></table></div></div></section>';
}

/* ---------- Seviye testi ---------- */
let T = null;
function viewTest() {
  const Q2 = window.PBI_PLACEMENT;
  if (!T) T = { i: 0, score: {}, ans: [] };
  if (T.i >= Q2.length) {
    let lv = null; for (const L of LEVELS) { const n = Q2.filter(q => q.lv === L.id).length; if (n && (T.score[L.id] || 0) >= Math.ceil(n * 0.75)) lv = L.id; else break; }
    P.placement = lv; save();
    const total = T.ans.filter(Boolean).length; const nextL = LEVELS[lv ? LVI(lv) + 1 : 0];
    const rec = !lv || lv === 'A1' ? 'profesyonel' : lv === 'A2' || lv === 'B1' ? 'analist' : lv === 'B2' ? 'pl300' : 'gelistirici';
    const start = nextL ? LESSONS.find(l => l.lvl === nextL.id) : null;
    return '<div class="wrap"><div class="panel hero-main"><span class="eyebrow">Sonuç</span><h1>' + total + '/' + Q2.length + ' doğru · <em>' + (lv ? lv + ' · ' + lvName(lv) : 'Başlangıç') + '</em></h1><p>' + (lv ? lv + ' seviyesini geçtin. ' : 'A1’den başlamak en hızlı yol olacak. ') + (nextL ? 'Önerilen başlangıç: <b>' + nextL.id + ' · ' + nextL.name + '</b> — ' + esc(nextL.desc) : 'Tüm seviyeleri geçtin; Final Projesi ile kendini sına.') + '</p><div class="row">' + (start ? '<button class="btn pri" data-lesson="' + start.id + '">' + esc(start.title) + ' dersiyle başla</button>' : '<button class="btn pri" data-go="final">Final projesi</button>') + '<button class="btn" data-go="path" data-id="' + rec + '">Önerilen patika: ' + esc(PMAP[rec].name) + '</button><button class="btn ghost" data-act="test-again">Testi tekrar çöz</button></div></div>' +
      '<div class="panel lessons">' + LEVELS.map(L => { const n = Q2.filter(q => q.lv === L.id).length; const s = T.score[L.id] || 0; return '<div class="litem" style="cursor:default"><span>' + lvBadge(L.id) + '</span><span><b>' + L.name + '</b><small>' + s + '/' + n + ' doğru · ' + (s >= Math.ceil(n * 0.75) ? 'geçildi' : 'çalışılmalı') + '</small></span><span class="bar" style="width:120px"><i style="width:' + (s / n * 100) + '%"></i></span></div>'; }).join('') + '</div></div>';
  }
  const q = Q2[T.i];
  return '<div class="wrap">' + head('Seviye testi · ' + (T.i + 1) + '/' + Q2.length, 'Nereden başlamalısın?', null, 'test') + '<div class="bar"><i style="width:' + (T.i / Q2.length * 100) + '%"></i></div><div class="panel brief" style="max-width:760px">' + lvBadge(q.lv) + '<div class="q">' + esc(q.q) + '</div><div class="mc">' + q.o.map((o, i) => '<button data-tq="' + i + '"><span class="key">' + String.fromCharCode(65 + i) + '</span><span>' + esc(o) + '</span></button>').join('') + '<button data-tq="-1"><span class="key">?</span><span>Bilmiyorum</span></button></div></div></div>';
}

/* ---------- Sözlük ---------- */
let dq = '';
function viewDict() { return '<div class="wrap">' + head('Sözlük', 'Power BI terimleri', window.PBI_GLOSSARY.length + ' terim.', 'dict') + '<input class="input" id="dQ" placeholder="Terim ara" value="' + esc(dq) + '" style="max-width:340px" aria-label="Terim ara"><div class="panel dict" id="dList">' + dList() + '</div></div>'; }
function dList() { const q = dq.trim().toLocaleLowerCase('tr'); const it = window.PBI_GLOSSARY.filter(g => !q || (g[0] + ' ' + g[1]).toLocaleLowerCase('tr').includes(q)).sort((a, b) => a[0].localeCompare(b[0], 'tr')); return it.length ? '<dl>' + it.map(g => '<div><dt>' + esc(g[0]) + '</dt><dd>' + esc(g[1]) + '</dd></div>').join('') + '</dl>' : '<div class="empty">Sonuç yok.</div>'; }

/* ---------- Görünüm kayıtları ---------- */
view('home', { render: viewHome, hash: '' });
view('paths', { render: viewPaths, hash: 'patikalar' });
view('path', { render: id => viewPath(id), hash: 'patika' });
view('curr', { render: viewCurr, hash: 'dersler' });
view('lesson', { render: viewLesson, mount: mountLesson, hash: 'ders' });
view('model', { render: viewModel, mount: mountModel, hash: 'model' });
view('studio', { render: viewStudio, mount: mountStudio, hash: 'studyo' });
view('formulas', { render: viewFormulas, hash: 'formuller' });
view('test', { render: viewTest, hash: 'test' });
view('dict', { render: viewDict, hash: 'sozluk' });
view('more', { render: viewMore, hash: 'menu' });

/* ---------- Olaylar ---------- */
document.addEventListener('click', ev => {
  const t = ev.target.closest('button, [data-tbl], a'); if (!t) return;
  const d = t.dataset;
  if (d.go) { ev.preventDefault(); if (d.lv) currFilter.lv = d.lv; return go(d.go, d.id); }
  if (d.lesson) return go('lesson', d.lesson, { ctx: d.ctx || (S.view === 'path' ? S.id : S.view === 'lesson' ? S.ctx : null) });
  if (d.step !== undefined) { S.step = +d.step; render(); window.scrollTo(0, 0); return; }
  if (d.lvf) { currFilter.lv = d.lvf; document.querySelectorAll('[data-lvf]').forEach(b => b.setAttribute('aria-pressed', b.dataset.lvf === d.lvf)); $('#currList').innerHTML = currList(); return; }
  if (d.mc !== undefined) {
    const l = LMAP[S.id], i = S.step - 1, e = l.ex[i], k = exKey(l, i); const ch = +d.mc;
    document.querySelectorAll('#mc button').forEach(b => b.classList.remove('right', 'wrong'));
    if (ch === e.a) { t.classList.add('right'); $('#mcFb').innerHTML = '<div class="msg ok"><b>Doğru.</b>' + (e.why || '') + (e.explain ? '<div class="explain">' + e.explain + '</div>' : '') + '</div>'; solved(l, i, k); }
    else { t.classList.add('wrong'); $('#mcFb').innerHTML = '<div class="msg err"><b>Tekrar dene.</b>Bu seçenek doğru değil.</div>'; }
    return;
  }
  if (d.tq !== undefined) { const q = window.PBI_PLACEMENT[T.i]; const ok = +d.tq === q.a; if (ok) T.score[q.lv] = (T.score[q.lv] || 0) + 1; T.ans.push(ok); T.i++; render(); return; }
  if (d.tbl && S.view === 'model') return showTable(d.tbl);
  if (d.try) return openInStudio(d.try);
  if (d.smode) { ST.mode = d.smode; saveStudio(); render(); return; }
  if (d.side) { ST.side = d.side; saveStudio(); document.querySelectorAll('[data-side]').forEach(b => b.setAttribute('aria-pressed', b.dataset.side === d.side)); $('#sideList').innerHTML = sideList(); return; }
  if (d.ins) { if (SED) { SED.insert(d.ins); SED.focus(); } return; }
  if (d.styil) { const y = +d.styil; ST.yil = ST.yil.includes(y) ? ST.yil.filter(x => x !== y) : ST.yil.concat([y]); t.setAttribute('aria-pressed', ST.yil.includes(y)); saveStudio(); studioRun(); return; }
  if (d.stkanal) { const k = d.stkanal; ST.kanal = ST.kanal.includes(k) ? ST.kanal.filter(x => x !== k) : ST.kanal.concat([k]); t.setAttribute('aria-pressed', ST.kanal.includes(k)); saveStudio(); studioRun(); return; }
  if (d.fcat) { fq.cat = d.fcat; document.querySelectorAll('[data-fcat]').forEach(b => b.setAttribute('aria-pressed', b.dataset.fcat === d.fcat)); $('#fList').innerHTML = fList(); enhance($('#fList')); return; }
  const act = d.act; if (!act) return;
  if (act === 'hint') { const e = LMAP[S.id].ex[S.step - 1]; $('#hintBox').innerHTML = '<div class="tip" style="margin:0"><b>İpucu</b>' + esc(e.hint) + '</div>'; return; }
  if (act === 'sol') { const e = LMAP[S.id].ex[S.step - 1]; $('#solBox').innerHTML = '<div class="codebox"><pre class="dax" data-done="1">' + hl((e.name ? e.name + ' =\n' : '') + e.sol) + '</pre></div>' + (e.explain ? '<div class="explain"><b>Mantığı</b>' + e.explain + '</div>' : '') + '<div class="row" style="margin-top:6px"><button class="btn sm" data-act="take-sol">Editöre al</button></div>'; return; }
  if (act === 'take-sol') { const e = LMAP[S.id].ex[S.step - 1]; ED.set(e.sol); return; }
  if (act === 'ex-studio') { const e = LMAP[S.id].ex[S.step - 1]; const src = ED.get(); openInStudio(e.t === 'query' ? src : (X.stripDef(src).name ? src : e.name + ' = ' + src)); return; }
  if (act === 'check') return checkEx(true);
  if (act === 'run') return checkEx(false);
  if (act === 'reset-ed') { const e = LMAP[S.id].ex[S.step - 1]; ED.set(e.start || (e.t === 'query' ? 'EVALUATE\n' : '')); $('#out').innerHTML = ''; return; }
  if (act === 'read-done') { const l = LMAP[S.id]; if (!P.done[l.id]) { P.done[l.id] = true; addXP(5); save(); } render(); return; }
  if (act === 'st-run') return studioRun();
  if (act === 'st-clear') { SED.set(''); $('#stOut').innerHTML = ''; return; }
  if (act === 'st-save') { const src = SED.get(); const dd = X.stripDef(src); if (!dd.name) { toast('Kaydetmek için ölçüye ad ver: Ad = ifade'); return; } const er = X.check(src); if (er) { toast('Önce hatayı düzelt: ' + er); return; } if (upsertMine(dd.name, dd.expr.trim())) { ST.side = 'measures'; saveStudio(); document.querySelectorAll('[data-side]').forEach(b => b.setAttribute('aria-pressed', b.dataset.side === 'measures')); $('#sideList').innerHTML = sideList(); } return; }
  if (act === 'mine-del') { P.mine.splice(+d.i, 1); save(); $('#sideList').innerHTML = sideList(); toast('Ölçü silindi'); return; }
  if (act === 'mine-edit') { const m = P.mine[+d.i]; SED.set(m.name + ' =\n' + m.expr); studioRun(); return; }
  if (act === 'test-again') { T = null; render(); return; }
  if (act === 'reset-ask') { $('#resetBox').innerHTML = '<span class="muted" style="font-size:.85rem">Tüm ilerleme, XP ve kayıtlı ölçüler silinecek.</span><button class="btn sm" data-act="reset-yes">Evet, sıfırla</button><button class="btn sm ghost" data-act="reset-no">Vazgeç</button>'; return; }
  if (act === 'reset-yes') { Object.keys(P).forEach(k => delete P[k]); Object.assign(P, FRESH()); save(); toast('İlerleme sıfırlandı'); render(); return; }
  if (act === 'reset-no') { render(); return; }
});
document.addEventListener('keydown', ev => { if ((ev.key === 'Enter' || ev.key === ' ') && ev.target.matches('[data-tbl]:not(button)')) { ev.preventDefault(); ev.target.dispatchEvent(new MouseEvent('click', { bubbles: true })); } });
document.addEventListener('input', ev => {
  if (ev.target.id === 'currQ') { currFilter.q = ev.target.value; $('#currList').innerHTML = currList(); }
  if (ev.target.id === 'fQ') { fq.q = ev.target.value; $('#fList').innerHTML = fList(); enhance($('#fList')); }
  if (ev.target.id === 'dQ') { dq = ev.target.value; $('#dList').innerHTML = dList(); }
});
document.addEventListener('change', ev => {
  const id = ev.target.id;
  if (id === 'stAxis') { ST.axis = ev.target.value; saveStudio(); studioRun(); }
  if (id === 'stAxis2') { ST.axis2 = ev.target.value; saveStudio(); studioRun(); }
  if (id === 'stChart') { ST.chart = ev.target.value; saveStudio(); studioRun(); }
  if (id === 'stEx' && ev.target.value !== '') { const x = STUDIO_EX[+ev.target.value]; SED.set(x[2]); if (x[3]) { ST.axis = x[3]; const a = $('#stAxis'); if (a) a.value = x[3]; } if (x[4]) { ST.chart = x[4]; const c = $('#stChart'); if (c) c.value = x[4]; } ST.axis2 = ''; const a2 = $('#stAxis2'); if (a2) a2.value = ''; saveStudio(); studioRun(); ev.target.value = ''; }
});
document.addEventListener('toggle', e => { const el = e.target; if (el && el.matches && el.matches('details.guide')) { P.gclosed = P.gclosed || {}; P.gclosed[el.dataset.guide] = !el.open; save(); } }, true);

/* ---------- Başlat ---------- */
function fromHash() {
  const h = decodeURIComponent((location.hash || '').slice(1));
  const i = h.indexOf('-'); const pre = i < 0 ? h : h.slice(0, i); const id = i < 0 ? null : h.slice(i + 1);
  const v = Object.keys(VIEWS).find(k => k !== 'home' && (VIEWS[k].hash || k) === pre);
  if (!v) { S = { view: 'home', id: null, step: 0, ctx: null }; return; }
  if (v === 'lesson' && !LMAP[id]) { S = { view: 'curr', id: null, step: 0 }; return; }
  S = { view: v, id, step: 0, ctx: v === 'path' ? id : null };
}
function start() {
  window.addEventListener('hashchange', () => { if (location.hash === lastHash) return; lastHash = location.hash; fromHash(); render(); window.scrollTo(0, 0); });
  let rz = null; window.addEventListener('resize', () => { clearTimeout(rz); rz = setTimeout(() => { const d = VIEWS[S.view]; if (d && d.resize) d.resize(); }, 250); });
  fromHash(); render();
}
window.PBI_CORE = { X, V, MODEL, $, esc, hl, enhance, go, render, view, P, save, toast, addXP, measureSet, fmtOf, guessFmt, LIB, LIBMAP, LEVELS, LVI, lvBadge, lvName, LESSONS, LMAP, ic, head, guide, spanW, mainW, bindMarks, openInStudio, daxBlock, daxDeps, resultTable, parseCol, fmtVal, start, state: () => S };
})();

