/* ===== PBIPatika v2: 6 seviye, rehberler, biçim bölmesi, dashboard çekmecesi, laboratuvar, püf noktaları, menüler, final ===== */
:root{ --lv1:#2F9A5A; --lv2:#1E8A8A; --lv3:#3866D1; --lv4:#7A4FD0; --lv5:#B8418F; --lv6:#C2410C; --muted-mark:#C9C5BA }
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){ --lv1:#4CC27E; --lv2:#3CB8B8; --lv3:#6E93F0; --lv4:#A784F0; --lv5:#E06BB6; --lv6:#F07A45; --muted-mark:#4A473E }}
:root[data-theme="dark"]{ --lv1:#4CC27E; --lv2:#3CB8B8; --lv3:#6E93F0; --lv4:#A784F0; --lv5:#E06BB6; --lv6:#F07A45; --muted-mark:#4A473E }

/* Seviye rozetleri */
.lv{min-width:34px}
.lv.lv1{background:var(--lv1)} .lv.lv2{background:var(--lv2)} .lv.lv3{background:var(--lv3)} .lv.lv4{background:var(--lv4)} .lv.lv5{background:var(--lv5)} .lv.lv6{background:var(--lv6)}

/* Menü grupları */
.navgrp{display:block; font-size:.66rem; text-transform:uppercase; letter-spacing:.1em; font-weight:700; color:var(--muted); padding:12px 10px 4px; opacity:.8}
.navgrp:first-child{padding-top:0}
.side{overflow-y:auto}

/* Sayfa başlığı ve rehber */
.phead{display:flex; flex-direction:column; gap:6px}
.phead p{margin:0; max-width:72ch}
.guide{background:var(--surface); border:1px solid var(--line); border-left:3px solid var(--accent); border-radius:var(--r); padding:0}
.guide summary{cursor:pointer; list-style:none; display:flex; gap:10px; align-items:center; padding:11px 14px; font-weight:600; font-size:.92rem}
.guide summary::-webkit-details-marker{display:none}
.guide summary::after{content:"▾"; margin-left:auto; color:var(--muted); transition:transform .15s}
.guide:not([open]) summary::after{transform:rotate(-90deg)}
.guide .gi{display:inline-grid; place-items:center; width:20px; height:20px; border-radius:50%; background:var(--accent-soft); color:var(--accent-text); font-family:var(--f-display); font-weight:800; font-size:.8rem; font-style:italic}
.guide .gbody{padding:0 16px 14px 44px; font-size:.92rem}
.guide .gbody p{margin:0 0 8px; max-width:80ch}
.guide ul{margin:0; padding-left:18px; display:grid; gap:4px}
.guide li b{margin-right:4px}

/* Ana sayfa seviye haritası */
.climb6{display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:10px}
.stop6{display:flex; flex-direction:column; gap:6px; align-items:flex-start; text-align:left; padding:14px; background:var(--surface); border:1px solid var(--line); border-top:4px solid var(--c, var(--lv1)); border-radius:var(--r); min-width:0}
.stop6:hover{border-color:var(--muted); border-top-color:var(--c)}
.stop6.lv1{--c:var(--lv1)} .stop6.lv2{--c:var(--lv2)} .stop6.lv3{--c:var(--lv3)} .stop6.lv4{--c:var(--lv4)} .stop6.lv5{--c:var(--lv5)} .stop6.lv6{--c:var(--lv6)}
.stop6 .code{font-family:var(--f-display); font-weight:800; font-size:1.4rem; color:var(--c)}
.stop6 small{color:var(--muted); font-size:.8rem; line-height:1.4}
.stop6 .daxlen{font-family:var(--f-mono); font-size:.7rem; color:var(--muted); background:var(--surface-2); border-radius:5px; padding:2px 6px}
.stop6 .bar{width:100%; margin-top:auto} .stop6 .bar i{background:var(--c)}
.cando{display:grid; grid-template-columns:minmax(0,1fr) 240px; gap:16px; padding:14px 18px; margin-bottom:10px}
.cando ul{margin:6px 0 0; padding-left:0; list-style:none; display:grid; gap:4px; font-size:.9rem}
.cando li{padding-left:22px; position:relative}
.cando li::before{content:"✓"; position:absolute; left:2px; color:var(--ok); font-weight:700}
.cando-side{display:flex; flex-direction:column; gap:6px; border-left:1px solid var(--line); padding-left:16px}
.cando-side b{font-family:var(--f-mono); font-size:.8rem; font-weight:500}
.explain{margin-top:8px; padding-top:8px; border-top:1px dashed color-mix(in srgb, var(--ok) 35%, transparent); font-size:.9rem}
.explain b{display:block; font-size:.72rem; text-transform:uppercase; letter-spacing:.07em; color:var(--muted)}

/* Model */
.er path.inactive{stroke-dasharray:5 4; opacity:.7}
.er .card1{fill:var(--muted); font-size:10px; font-family:var(--f-mono)}
.ptables{padding:14px 18px; display:flex; flex-direction:column; gap:8px}

/* Görsel kütüphanesi ek sınıfları */
.ref{stroke-width:1.4; fill:none}
.ref-avg{stroke:var(--s2); stroke-dasharray:5 4}
.ref-med{stroke:var(--s7); stroke-dasharray:2 3}
.ref-min{stroke:var(--axis); stroke-dasharray:1 3}
.ref-const{stroke:var(--ink); stroke-dasharray:6 3}
.ref-trend{stroke:var(--s2); stroke-width:1.6}
.ref-fc{stroke:var(--s1); stroke-dasharray:4 3}
.fband{fill:var(--s1); opacity:.13}
.vref{fill:var(--ink); font-size:10px; font-weight:600}
.vbreak{stroke:var(--err); stroke-width:1.5}
.vlabin{fill:#fff; font-size:10px; font-weight:600}
.vspark{display:inline-block; vertical-align:middle}
.kspark{margin-top:6px}
.vmap{fill:var(--surface-2); stroke:var(--line); stroke-width:1}
.dlink{fill:none; stroke:var(--line); stroke-width:1.4}
.dnode{cursor:pointer}
.dnode.sel rect{stroke:var(--accent); stroke-width:2}
.svgm{display:block; height:26px; width:auto}
.vcard.sm b{font-size:1.5rem}
.vkpi b{font-size:2rem}
.vlegend.top{margin-bottom:4px}
.vtable.banded tbody tr:nth-child(even):not(.tot) td{background:var(--surface-2)}
.vtable.compact td,.vtable.compact th{padding:4px 7px}
.cfi{display:inline-block; width:14px; font-size:.75rem; margin-right:3px}
.cfi.ok{color:var(--ok)} .cfi.bad{color:var(--err)}
.sl-dd{border:1px solid var(--line); background:var(--surface); border-radius:6px; padding:5px 8px; font-size:.84rem; min-width:150px; max-width:240px}
.sl-list{display:flex; flex-direction:column; gap:3px; font-size:.86rem; max-height:180px; overflow:auto; padding:4px 0}
.sl-list label{display:flex; gap:6px; align-items:center}
.vtip.wide{max-width:280px; min-width:240px}
.tpage{margin-top:8px; padding-top:8px; border-top:1px solid var(--line); display:flex; flex-direction:column; gap:6px}
.tpage-h{font-size:.7rem; text-transform:uppercase; letter-spacing:.07em; color:var(--muted); font-weight:600}
.tcards{display:grid; grid-template-columns:repeat(3,1fr); gap:6px}
.tcards div{background:var(--surface-2); border-radius:6px; padding:5px 6px; display:flex; flex-direction:column}
.tcards small{font-size:.66rem; color:var(--muted)} .tcards b{font-size:.84rem}
.tsl{font-size:.7rem; color:var(--muted)}
.heat{overflow-x:auto} .heat table{border-collapse:separate; border-spacing:2px; font-size:.74rem; width:100%}
.heat th{font-weight:600; color:var(--muted); font-size:.7rem; padding:2px 4px; text-align:center}
.heat td{text-align:center; padding:6px 2px; border-radius:3px; font-variant-numeric:tabular-nums; min-width:34px}
.coh{overflow-x:auto}
.narr{margin:0; font-size:.98rem; line-height:1.6; max-width:95ch}
.tsub{font-size:.86rem; color:var(--muted)}
.rlsbar{background:var(--accent-soft); border:1px solid color-mix(in srgb, var(--accent) 45%, transparent); border-radius:8px; padding:10px 12px; font-size:.9rem}
.rlsbar.off{background:var(--surface-2); border-color:var(--line)}
.empty{color:var(--muted); font-size:.9rem; padding:16px; text-align:center}
.hscroll{overflow-x:auto}

/* ===== Görseller: biçim bölmesi benzetimi ===== */
.vstrip{display:flex; gap:14px; overflow-x:auto; padding:4px 2px 10px; scroll-snap-type:x proximity; border-bottom:1px solid var(--line)}
.vsg{display:flex; flex-direction:column; gap:6px; flex:none}
.vsg-row{display:flex; gap:6px}
.vsg-row button{display:flex; flex-direction:column; align-items:center; gap:4px; width:84px; padding:6px 4px; border:1px solid var(--line); border-radius:8px; background:var(--surface); scroll-snap-align:start}
.vsg-row button span{font-size:.7rem; line-height:1.2; text-align:center; color:var(--muted)}
.vsg-row button .vthumb{width:56px; height:35px}
.vsg-row button[aria-pressed="true"]{border-color:var(--accent-text); background:var(--accent-soft); box-shadow:inset 0 0 0 1px var(--accent-text)}
.vsg-row button[aria-pressed="true"] span{color:var(--accent-text); font-weight:600}
.vsim{display:grid; grid-template-columns:minmax(0,1fr) 360px; gap:14px; align-items:start}
.vcanvas{padding:16px 18px; display:flex; flex-direction:column; gap:12px; min-width:0}
.vc-head{display:flex; justify-content:space-between; align-items:center; gap:10px}
.vc-head .vthumb{width:64px; height:40px}
.vlast{border:1px solid color-mix(in srgb, var(--s1) 40%, transparent); background:color-mix(in srgb, var(--s1) 8%, var(--surface)); border-radius:8px; padding:10px 12px; font-size:.9rem}
.vlast p{margin:6px 0 0}
.vlast.idle{border-style:dashed; border-color:var(--line); background:none; color:var(--muted)}
.vframe{background:var(--surface); border-radius:8px; padding:12px; display:flex; flex-direction:column; gap:8px; border:1px solid transparent}
.vframe.bd{border-color:var(--ink)} .vframe.sh{box-shadow:0 6px 18px rgba(0,0,0,.14)} .vframe.nobg{background:repeating-conic-gradient(var(--surface-2) 0 25%, transparent 0 50%) 0 0/16px 16px}
.vtitle{font-weight:600; font-size:.92rem}
.vtitle.dyn{font-family:var(--f-display); font-size:1.05rem}
.vpane{position:sticky; top:12px; max-height:calc(100vh - 24px); display:flex; flex-direction:column; overflow:hidden}
.ptabs{display:grid; grid-template-columns:repeat(4,1fr); border-bottom:1px solid var(--line)}
